// Входные данные: товар с изменившейся ценой
const product = $input.first().json;

const prompt = `Ты аналитик ценообразования для продавцов на Wildberries.

Товар: ${product.product_name}
Бренд: ${product.brand}
Было: ${product.previous_price} ₽
Стало: ${product.price} ₽
Изменение: ${product.price_change_percent}%
Рейтинг: ${product.rating}
Отзывов: ${product.feedbacks}

Проанализируй это изменение цены и дай краткие рекомендации продавцу (2-3 предложения):
- Почему конкурент мог изменить цену?
- Что делать продавцу?
- Стоит ли менять свою цену?

Формат ответа JSON:
{
  "analysis": "Краткий анализ (2-3 предложения)",
  "recommendation": "Рекомендация (1-2 предложения)",
  "action": "СНИЗИТЬ" | "ОСТАВИТЬ" | "ПОВЫСИТЬ",
  "suggested_price": 2499
}`;

return {
  json: {
    ...product,
    ai_prompt: prompt
  }
};

const aiResponse = $input.first().json;
const product = $node['Prepare AI Prompt'].json;

let analysis = {
  analysis: 'Конкурент снизил цену, возможно из-за распродажи.',
  recommendation: 'Следите за динамикой. Если спрос упал - снижайте.',
  action: 'ОСТАВИТЬ',
  suggested_price: product.price
};

try {
  const content = aiResponse.choices[0].message.content;
  const parsed = JSON.parse(content);
  analysis = {
    analysis: parsed.analysis || analysis.analysis,
    recommendation: parsed.recommendation || analysis.recommendation,
    action: parsed.action || analysis.action,
    suggested_price: parsed.suggested_price || product.price
  };
} catch (e) {
  // Используем fallback
}

const actionEmoji = {
  'СНИЗИТЬ': '📉',
  'ОСТАВИТЬ': '➡️',
  'ПОВЫСИТЬ': '📈'
};

const message = `🤖 *AI Анализ изменения цены*\n\n` +
  `📦 ${product.product_name}\n` +
  `💰 Было: ${product.previous_price} ₽ → Стало: ${product.price} ₽\n` +
  `${product.price_change_percent > 0 ? '📈' : '📉'} ${Math.abs(product.price_change_percent)}%\n\n` +
  `💡 *Анализ:*\n${analysis.analysis}\n\n` +
  `🎯 *Рекомендация:*\n${analysis.recommendation}\n\n` +
  `${actionEmoji[analysis.action]} *Действие:* ${analysis.action}\n` +
  `💵 *Предлагаемая цена:* ${analysis.suggested_price} ₽`;

return {
  json: {
    chat_id: product.chat_id,
    message: message,
    ai_analysis: analysis.analysis,
    ai_recommendation: analysis.recommendation,
    ai_action: analysis.action,
    ai_suggested_price: analysis.suggested_price
  }
};
